//! Static model metadata generated by `#[derive(Model)]` (the equivalent of `schema.prisma`).

use serde::Serialize;
use serde::de::DeserializeOwned;

/// Scalar type of a field (the scalar types of `schema.prisma`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldKind {
    Int,
    BigInt,
    Float,
    Boolean,
    String,
    DateTime,
    Json,
    /// `Decimal` (decimal.js semantics, see [`crate::Decimal`]).
    Decimal,
    /// `Bytes`
    Bytes,
    /// A schema `enum` (see [`EnumMeta`]).
    Enum,
    /// Not a column: a relation field.
    Relation,
}

impl FieldKind {
    /// Schema name of the type (used in error messages).
    pub fn schema_name(&self) -> &'static str {
        match self {
            FieldKind::Int => "Int",
            FieldKind::BigInt => "BigInt",
            FieldKind::Float => "Float",
            FieldKind::Boolean => "Boolean",
            FieldKind::String => "String",
            FieldKind::DateTime => "DateTime",
            FieldKind::Json => "Json",
            FieldKind::Decimal => "Decimal",
            FieldKind::Bytes => "Bytes",
            FieldKind::Enum => "Enum",
            FieldKind::Relation => "Relation",
        }
    }
    /// Numeric kinds (`increment`, `_sum`, `_avg`, ...).
    pub fn is_numeric(&self) -> bool {
        matches!(self, FieldKind::Int | FieldKind::BigInt | FieldKind::Float | FieldKind::Decimal)
    }
}

/// `@default(...)`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DefaultValue {
    /// `@default(autoincrement())`
    Autoincrement,
    /// `@default(now())`
    Now,
    /// `@default(uuid())` (v4)
    Uuid,
    /// `@default(cuid())`
    Cuid,
    /// A literal, encoded as JSON (`false`, `0`, `"draft"`, `[]`, an enum value `"ADMIN"`).
    Literal(&'static str),
    /// `@default(dbgenerated("gen_random_uuid()"))`: the database computes it.
    DbGenerated(&'static str),
    /// `@default(uuid(7))`
    UuidV7,
    /// `@default(cuid(2))`
    Cuid2,
    /// `@default(nanoid())` / `@default(nanoid(n))`
    Nanoid(u8),
    /// `@default(ulid())`
    Ulid,
}

/// Kind of relation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RelationKind {
    /// `posts Post[]`
    HasMany,
    /// `profile Profile?` (the foreign key lives on the other model).
    HasOne,
    /// `author User @relation(fields: [authorId], references: [id])`
    BelongsTo,
    /// Implicit many-to-many (`tags Tag[]` + `posts Post[]`, join table `_PostToTag`).
    ManyToMany,
}

/// Referential actions (`onDelete` / `onUpdate`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReferentialAction {
    Cascade,
    Restrict,
    NoAction,
    SetNull,
    SetDefault,
}

impl ReferentialAction {
    pub fn sql(&self) -> &'static str {
        match self {
            ReferentialAction::Cascade => "CASCADE",
            ReferentialAction::Restrict => "RESTRICT",
            ReferentialAction::NoAction => "NO ACTION",
            ReferentialAction::SetNull => "SET NULL",
            ReferentialAction::SetDefault => "SET DEFAULT",
        }
    }
}

/// `@relation(...)`.
#[derive(Debug, Clone, Copy)]
pub struct RelationMeta {
    pub kind: RelationKind,
    pub target: fn() -> &'static ModelMeta,
    /// `belongs_to`: local scalar fields holding the foreign key.
    pub fields: &'static [&'static str],
    /// `belongs_to`: referenced fields on the target (default: its id).
    /// `has_many` / `has_one`: the foreign key fields on the target (default: inferred
    /// from the target's `belongs_to` relation pointing back to this model).
    pub references: &'static [&'static str],
    pub on_delete: Option<ReferentialAction>,
    pub on_update: Option<ReferentialAction>,
    pub name: Option<&'static str>,
    /// `@relation(map: "...")`: name of the foreign key constraint.
    pub map: Option<&'static str>,
}

/// A model field.
#[derive(Debug, Clone, Copy)]
pub struct FieldMeta {
    /// Name used in queries and in the serialized struct (honours `#[serde(rename...)]`).
    pub name: &'static str,
    pub rust_name: &'static str,
    /// Column name in the database (`@map`).
    pub column: &'static str,
    pub kind: FieldKind,
    pub optional: bool,
    /// Relation list (`Post[]`) or scalar list (`String[]`).
    pub list: bool,
    pub is_id: bool,
    pub is_unique: bool,
    pub default: Option<DefaultValue>,
    pub updated_at: bool,
    pub relation: Option<RelationMeta>,
    /// `@db.*` native type, without the `@db.` prefix (`Uuid`, `Date`, `Decimal(20, 2)`, `VarChar(64)`).
    pub native_type: Option<&'static str>,
    /// The enum of an `Enum` field.
    pub enum_meta: Option<fn() -> &'static EnumMeta>,
}

/// A value of a schema enum.
#[derive(Debug, Clone, Copy)]
pub struct EnumValueMeta {
    /// Name in the schema / client (`ADMIN`).
    pub name: &'static str,
    /// Value stored in the database (`@map`), by default the name.
    pub db_name: &'static str,
}

/// `enum Role { ... }`
#[derive(Debug)]
pub struct EnumMeta {
    /// `Role`
    pub name: &'static str,
    /// Database type name (`@@map`), by default the name.
    pub db_name: &'static str,
    /// `@@schema`
    pub schema: Option<&'static str>,
    pub values: &'static [EnumValueMeta],
}

impl EnumMeta {
    /// Database value of a client value.
    pub fn to_db(&self, name: &str) -> Option<&'static str> {
        self.values.iter().find(|v| v.name == name).map(|v| v.db_name)
    }
    /// Client value of a database value.
    pub fn from_db(&self, db: &str) -> Option<&'static str> {
        self.values.iter().find(|v| v.db_name == db).map(|v| v.name)
    }
    /// `"ADMIN" | "MERCHANT"` (for error messages).
    pub fn variants_list(&self) -> String {
        self.values.iter().map(|v| format!("\"{}\"", v.name)).collect::<Vec<_>>().join(", ")
    }
}

/// Implemented for every type usable as a scalar field; `#[derive(OrmEnum)]` implements it for enums.
pub trait ScalarType {
    const KIND: FieldKind;
    const ENUM: Option<fn() -> &'static EnumMeta> = None;
}

impl<T: ScalarType> ScalarType for Option<T> {
    const KIND: FieldKind = T::KIND;
    const ENUM: Option<fn() -> &'static EnumMeta> = T::ENUM;
}

/// Implemented by `#[derive(OrmEnum)]`.
pub trait OrmEnum: Sized + Copy + Send + Sync + 'static {
    fn enum_meta() -> &'static EnumMeta;
    /// The client name of the value (`"ADMIN"`).
    fn as_str(&self) -> &'static str;
    /// All values in schema order (`Object.values(Role)`).
    fn values() -> &'static [Self];
    /// From the client name.
    fn from_name(s: &str) -> Option<Self> {
        Self::values().iter().copied().find(|v| v.as_str() == s)
    }
}

macro_rules! scalar_type {
    ($kind:ident: $($t:ty),*) => {$(
        impl ScalarType for $t { const KIND: FieldKind = FieldKind::$kind; }
    )*};
}
scalar_type!(Int: i8, i16, i32, u8, u16);
scalar_type!(BigInt: i64, u32, u64, isize, usize);
scalar_type!(Float: f32, f64);
scalar_type!(Boolean: bool);
scalar_type!(String: String, uuid::Uuid);
scalar_type!(DateTime: crate::DateTime, chrono::DateTime<chrono::Utc>, chrono::NaiveDateTime, chrono::NaiveDate);
scalar_type!(Json: serde_json::Value);
scalar_type!(Decimal: crate::Decimal);
scalar_type!(Bytes: Vec<u8>);

/// `@@unique([a, b])`: a compound unique key.
#[derive(Debug, Clone, Copy)]
pub struct UniqueMeta {
    /// Name of the `WhereUniqueInput` key (`a_b`, or `name:`).
    pub name: &'static str,
    /// Field names (as used in queries).
    pub fields: &'static [&'static str],
    /// Database constraint / index name (`map:`).
    pub map: Option<&'static str>,
}

/// `@@index([a, b])`
#[derive(Debug, Clone, Copy)]
pub struct IndexMeta {
    pub fields: &'static [&'static str],
    pub map: Option<&'static str>,
    /// `type: Hash | Gin | Gist | ...`
    pub kind: Option<&'static str>,
}

/// A column the client cannot read (`Unsupported("vector(384)")`); kept for `db push`.
#[derive(Debug, Clone, Copy)]
pub struct UnsupportedMeta {
    pub name: &'static str,
    pub column: &'static str,
    pub db_type: &'static str,
    pub optional: bool,
}

impl FieldMeta {
    pub fn is_scalar(&self) -> bool {
        self.relation.is_none()
    }
    pub fn is_relation(&self) -> bool {
        self.relation.is_some()
    }
    /// Scalar list (`String[]`).
    pub fn is_scalar_list(&self) -> bool {
        self.is_scalar() && self.list
    }
    /// Required on create (no default, not optional, not generated).
    pub fn is_required_on_create(&self) -> bool {
        self.is_scalar() && !self.optional && !self.list && self.default.is_none() && !self.updated_at
    }
    /// The enum of the field, if any.
    pub fn enum_meta(&self) -> Option<&'static EnumMeta> {
        self.enum_meta.map(|f| f())
    }
    /// The native type name without arguments (`Decimal(20, 2)` → `Decimal`).
    pub fn native_name(&self) -> Option<&'static str> {
        self.native_type.map(|t| t.split('(').next().unwrap_or(t).trim())
    }
}

/// A model (`model User { ... }`).
#[derive(Debug)]
pub struct ModelMeta {
    /// `User`
    pub name: &'static str,
    /// Table name (`@@map`), by default the model name.
    pub table: &'static str,
    /// `user` – as in `db.user().find_many(...)`.
    pub client_name: &'static str,
    pub fields: &'static [FieldMeta],
    /// `@@schema("...")`
    pub schema: Option<&'static str>,
    /// Primary key fields (one `@id` or `@@id([...])`).
    pub primary_key: &'static [&'static str],
    /// `@@id(name: ...)`: the `WhereUniqueInput` name (`a_b` by default).
    pub primary_key_name: Option<&'static str>,
    /// `@@id(map: ...)` / `@id(map: ...)`: the primary key constraint name.
    pub primary_key_map: Option<&'static str>,
    /// `@@unique([...])`
    pub uniques: &'static [UniqueMeta],
    /// `@@index([...])`
    pub indexes: &'static [IndexMeta],
    /// `Unsupported(...)` columns.
    pub unsupported: &'static [UnsupportedMeta],
    /// `view` instead of `model`.
    pub is_view: bool,
}

impl ModelMeta {
    pub fn field(&self, name: &str) -> Option<&'static FieldMeta> {
        self.fields.iter().find(|f| f.name == name)
    }
    /// Looks a field up by its query name or its Rust name.
    pub fn field_any(&self, name: &str) -> Option<&'static FieldMeta> {
        self.field(name).or_else(|| self.fields.iter().find(|f| f.rust_name == name || f.column == name))
    }
    pub fn scalars(&self) -> impl Iterator<Item = &'static FieldMeta> {
        self.fields.iter().filter(|f| f.is_scalar())
    }
    pub fn relations(&self) -> impl Iterator<Item = &'static FieldMeta> {
        self.fields.iter().filter(|f| f.is_relation())
    }
    /// The first primary key field (the only one unless the model has a `@@id`).
    pub fn id(&self) -> &'static FieldMeta {
        self.pk()[0]
    }
    /// Primary key fields, in order.
    pub fn pk(&self) -> Vec<&'static FieldMeta> {
        let fields: Vec<&'static FieldMeta> = self.primary_key.iter().filter_map(|n| self.field_any(n)).collect();
        if !fields.is_empty() {
            return fields;
        }
        let ids: Vec<&'static FieldMeta> = self.fields.iter().filter(|f| f.is_id).collect();
        if !ids.is_empty() {
            return ids;
        }
        // No id: the first unique (the schema requires one).
        if let Some(u) = self.uniques.first() {
            return u.fields.iter().filter_map(|n| self.field_any(n)).collect();
        }
        let u: Vec<&'static FieldMeta> = self.scalars().filter(|f| f.is_unique).take(1).collect();
        if u.is_empty() { self.scalars().take(1).collect() } else { u }
    }
    /// `true` when the primary key has more than one field.
    pub fn has_compound_pk(&self) -> bool {
        self.pk().len() > 1
    }
    /// Name of the compound id input (`a_b`), if the primary key is compound.
    pub fn compound_pk_name(&self) -> Option<String> {
        let pk = self.pk();
        if pk.len() < 2 {
            return None;
        }
        Some(self.primary_key_name.map(|s| s.to_string()).unwrap_or_else(|| pk.iter().map(|f| f.name).collect::<Vec<_>>().join("_")))
    }
    /// Fields of a compound unique input (`@@id` or `@@unique`) by name.
    pub fn compound_unique(&self, name: &str) -> Option<Vec<&'static FieldMeta>> {
        if self.compound_pk_name().as_deref() == Some(name) {
            return Some(self.pk());
        }
        self.uniques.iter().find(|u| u.name == name).map(|u| u.fields.iter().filter_map(|n| self.field_any(n)).collect())
    }
    /// Names of the compound unique inputs.
    pub fn compound_unique_names(&self) -> Vec<String> {
        let mut out = Vec::new();
        if let Some(n) = self.compound_pk_name() {
            out.push(n);
        }
        out.extend(self.uniques.iter().map(|u| u.name.to_string()));
        out
    }
    pub fn field_by_column(&self, column: &str) -> Option<&'static FieldMeta> {
        self.scalars().find(|f| f.column == column)
    }
}

/// Implemented by `#[derive(Model)]`.
pub trait Model: Serialize + DeserializeOwned + Send + Sync + Unpin + 'static {
    fn meta() -> &'static ModelMeta;
}

/// A set of models: `User`, `(User, Post)`, ... Used by `db_push::<(User, Post)>()`.
pub trait ModelSet {
    fn metas() -> Vec<&'static ModelMeta>;
}

impl<M: Model> ModelSet for M {
    fn metas() -> Vec<&'static ModelMeta> {
        vec![M::meta()]
    }
}

macro_rules! tuple_set {
    ($($t:ident),+) => {
        impl<$($t: ModelSet),+> ModelSet for ($($t,)+) {
            fn metas() -> Vec<&'static ModelMeta> {
                let mut v = Vec::new();
                $(v.extend($t::metas());)+
                v
            }
        }
    };
}
tuple_set!(A);
tuple_set!(A, B);
tuple_set!(A, B, C);
tuple_set!(A, B, C, D);
tuple_set!(A, B, C, D, E);
tuple_set!(A, B, C, D, E, F);
tuple_set!(A, B, C, D, E, F, G);
tuple_set!(A, B, C, D, E, F, G, H);
tuple_set!(A, B, C, D, E, F, G, H, I);
tuple_set!(A, B, C, D, E, F, G, H, I, J);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K, L);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K, L, M);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K, L, M, N);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K, L, M, N, O);
tuple_set!(A, B, C, D, E, F, G, H, I, J, K, L, M, N, O, P);

/// Resolved relation: how to join `from` with `to`.
#[derive(Debug, Clone)]
pub struct ResolvedRelation {
    pub kind: RelationKind,
    pub target: &'static ModelMeta,
    /// Fields on the parent model.
    pub parent_fields: Vec<&'static FieldMeta>,
    /// Matching fields on the target model.
    pub target_fields: Vec<&'static FieldMeta>,
    /// Implicit many-to-many: the join table and its columns (`A`/`B`).
    pub join: Option<JoinTable>,
}

/// The join table of an implicit many-to-many relation (`_CategoryToPost`, columns `A` and `B`).
#[derive(Debug, Clone)]
pub struct JoinTable {
    pub table: String,
    pub schema: Option<&'static str>,
    /// Column pointing to the parent model.
    pub parent_column: &'static str,
    /// Column pointing to the target model.
    pub target_column: &'static str,
}

impl ResolvedRelation {
    pub fn is_list(&self) -> bool {
        matches!(self.kind, RelationKind::HasMany | RelationKind::ManyToMany)
    }
}

/// Name of an implicit many-to-many relation: the explicit name or `AToB` (models sorted).
pub fn m2m_relation_name(a: &str, b: &str, name: Option<&str>) -> String {
    match name {
        Some(n) => n.to_string(),
        None => {
            let (x, y) = if a <= b { (a, b) } else { (b, a) };
            format!("{x}To{y}")
        }
    }
}

/// Resolves the join keys of a relation field.
pub fn resolve_relation(model: &'static ModelMeta, field: &'static FieldMeta) -> Result<ResolvedRelation, String> {
    let rel = field.relation.as_ref().ok_or_else(|| format!("`{}` is not a relation", field.name))?;
    let target = (rel.target)();
    let lookup = |m: &'static ModelMeta, names: &[&str]| -> Result<Vec<&'static FieldMeta>, String> {
        names
            .iter()
            .map(|n| m.field_any(n).ok_or_else(|| format!("Unknown field `{n}` on model `{}` in relation `{}.{}`", m.name, model.name, field.name)))
            .collect()
    };
    match rel.kind {
        RelationKind::ManyToMany => {
            let name = m2m_relation_name(model.name, target.name, rel.name);
            // Column A points to the model whose name sorts first.
            let self_rel = model.name == target.name;
            let (parent_column, target_column) = if self_rel {
                // Self relation: the field whose name sorts first is "A" (the two
                // fields of the relation are ordered by name).
                let other = target
                    .relations()
                    .find(|f| {
                        f.name != field.name
                            && f.relation.is_some_and(|r| r.kind == RelationKind::ManyToMany && m2m_relation_name(model.name, target.name, r.name) == name)
                    })
                    .map(|f| f.name)
                    .unwrap_or(field.name);
                if field.name <= other { ("A", "B") } else { ("B", "A") }
            } else if model.name < target.name {
                ("A", "B")
            } else {
                ("B", "A")
            };
            Ok(ResolvedRelation {
                kind: rel.kind,
                target,
                parent_fields: vec![model.id()],
                target_fields: vec![target.id()],
                join: Some(JoinTable { table: format!("_{name}"), schema: model.schema, parent_column, target_column }),
            })
        }
        RelationKind::BelongsTo => {
            if rel.fields.is_empty() {
                return Err(format!("Relation `{}.{}` needs `fields = \"...\"`", model.name, field.name));
            }
            let parent_fields = lookup(model, rel.fields)?;
            let target_fields = if rel.references.is_empty() { target.pk() } else { lookup(target, rel.references)? };
            Ok(ResolvedRelation { kind: rel.kind, target, parent_fields, target_fields, join: None })
        }
        RelationKind::HasMany | RelationKind::HasOne => {
            if !rel.references.is_empty() {
                let target_fields = lookup(target, rel.references)?;
                // Find the back-relation (if any) to know which parent fields are referenced.
                let back = target.relations().find(|f| {
                    let r = f.relation.as_ref().unwrap();
                    r.kind == RelationKind::BelongsTo
                        && (r.target)().name == model.name
                        && r.fields.iter().zip(target_fields.iter()).all(|(a, b)| target.field_any(a).map(|x| x.name) == Some(b.name))
                });
                let parent_fields = match back.and_then(|b| b.relation) {
                    Some(r) if !r.references.is_empty() => lookup(model, r.references)?,
                    _ => model.pk(),
                };
                return Ok(ResolvedRelation { kind: rel.kind, target, parent_fields, target_fields, join: None });
            }
            let back = target
                .relations()
                .filter(|f| {
                    let r = f.relation.as_ref().unwrap();
                    r.kind == RelationKind::BelongsTo
                        && (r.target)().name == model.name
                        && (rel.name.is_none() || r.name == rel.name)
                        && !(model.name == target.name && f.name == field.name)
                })
                .collect::<Vec<_>>();
            // With an unnamed relation, prefer the unnamed back relation.
            let back = if back.len() > 1 && rel.name.is_none() {
                let unnamed: Vec<_> = back.iter().copied().filter(|f| f.relation.unwrap().name.is_none()).collect();
                if unnamed.len() == 1 { unnamed } else { back }
            } else {
                back
            };
            match back.as_slice() {
                [b] => {
                    let r = b.relation.unwrap();
                    let target_fields = lookup(target, r.fields)?;
                    let parent_fields = if r.references.is_empty() { model.pk() } else { lookup(model, r.references)? };
                    Ok(ResolvedRelation { kind: rel.kind, target, parent_fields, target_fields, join: None })
                }
                [] => Err(format!(
                    "Relation `{}.{}`: model `{}` has no `belongs_to` relation pointing to `{}`; add `references = \"<fk field>\"`",
                    model.name, field.name, target.name, model.name
                )),
                _ => Err(format!(
                    "Relation `{}.{}` is ambiguous; give it a `name = \"...\"` or `references = \"<fk field>\"`",
                    model.name, field.name
                )),
            }
        }
    }
}
